"use client"

import React, { createContext, useContext, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { motion, AnimatePresence, useReducedMotion } from "framer-motion"
import { cn } from "@heroui/react"
import { SidebarSimpleIcon } from "@phosphor-icons/react"
import { ButtonBase } from "@sb-components/atoms/buttons/Button/ButtonBase"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { DragScrollArea } from "@sb-components/behaviors/DragScrollArea/DragScrollArea"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { FillAvailable } from "@sb-components/frames/FillAvailable/FillAvailable"

/**
 * `CollapsibleSidebar` — a content-agnostic shell for a left navigation sidebar
 * that collapses in place (no overlay/Drawer). Owns collapse/expand, the width
 * animation, persisting the choice to `localStorage`, and a `useSidebarCollapsed`
 * context so nav-row content can self-adapt to the icon-only rail. It never
 * inspects `children`. One leaf: `topSlot` presence and the collapsed flag are
 * data, so they are states, not separate leaves.
 */

/** Expanded panel width (full nav). */
const EXPANDED_WIDTH = "16rem"
/** Collapsed rail width — fits a centered icon row + the toggle. */
const COLLAPSED_WIDTH = "4rem"

/**
 * Named transition shapes (not inline object literals at the call site — check-inline-types
 * gate) for the width animation: a spring when motion is welcome, instant when the reader (or
 * their OS) asked for reduced motion.
 */
const SPRING_TRANSITION = { type: "spring" as const, stiffness: 420, damping: 38 }
const INSTANT_TRANSITION = { duration: 0 }
/** Title fade — quick cross-fade, same instant fallback under reduced motion. */
const FADE_TRANSITION = { duration: 0.15 }

/**
 * Collapsed flag shared with nav-row children so a row can drop to icon-only in
 * the rail. Internal UI chrome state — not an app store.
 */
const SidebarCollapsedContext = createContext(false)

/** Read whether the surrounding {@link CollapsibleSidebar} is collapsed (icon-rail). */
export const useSidebarCollapsed = (): boolean => useContext(SidebarCollapsedContext)

/** Props for the {@link CollapsibleSidebar} composite. */
export interface CollapsibleSidebarProps {
    /** Heading shown in the panel header (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /**
     * Stable key under which the collapsed flag persists in `localStorage`, so
     * the choice survives navigation between pages that share this sidebar.
     */
    storageKey: string
    /**
     * Optional node pinned BETWEEN the header and the scrollable nav — always
     * visible (outside the scroll area). Rendered inside the collapsed-context
     * provider, so it can adapt to the rail (e.g. a resume pill → play icon).
     */
    topSlot?: ReactNode
    /** The panel body — nav rows/groups; content-agnostic, this shell never inspects them. */
    children: ReactNode
}

/**
 * A left navigation sidebar that collapses IN PLACE: the panel animates between
 * a full {@link EXPANDED_WIDTH} (title + nav) and a thin {@link COLLAPSED_WIDTH}
 * rail (just the toggle), and the surrounding content reflows beside it — no
 * overlay/Drawer. Self-contained: the collapsed state is local UI chrome,
 * hydrated from storage on mount (SSR-safe — starts expanded, then syncs).
 *
 * @param props - {@link CollapsibleSidebarProps}
 */
export const CollapsibleSidebar = ({
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    topSlot,
    children,
}: CollapsibleSidebarProps) => {
    const reduceMotion = useReducedMotion()
    const [collapsed, setCollapsed] = useState(false)

    // hydrate the persisted choice after mount (avoids SSR/client mismatch)
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored !== null) {
            setCollapsed(stored === "true")
        }
    }, [storageKey])

    /** Flip + persist the collapsed flag. */
    const toggle = () => {
        setCollapsed((prev) => {
            const next = !prev
            window.localStorage.setItem(storageKey, String(next))
            return next
        })
    }

    // §10a: the vertical rhythm between header / topSlot / nav is owned by THIS
    // StackV's gap — no section carries its own margin (a prior draft put
    // `mb-6` on the header row itself, flagged by check-padding as a second
    // owner for the same seam).
    return (
        <SidebarCollapsedContext.Provider value={collapsed}>
            <motion.aside

                initial={false}
                animate={{ width: collapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH }}
                transition={reduceMotion ? INSTANT_TRANSITION : SPRING_TRANSITION}
                className={cn(
                    // ONE padding wrapper for the whole rail: p-6 expanded / px-3 py-6
                    // collapsed. No frame in this tree types an asymmetric inset, so this
                    // stays hand-written on the composite's own bespoke root (§13c precedent:
                    // Toolbar/ModalShell/DrawerShell do the same on theirs).
                    "flex h-full shrink-0 overflow-hidden border-r border-default",
                    collapsed ? "px-3 py-6" : "p-6",
                )}
            >
                <StackV
                    gap={6}
                    classNames={["min-h-0", "flex-1"]}
                    items={[
                        () => (
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                justify={collapsed ? "center" : "between"}
                                items={[
                                    () => (
                                        <AnimatePresence initial={false}>
                                            {!collapsed ? (
                                                <motion.div
                                                    key="title"
                                                    initial={{ opacity: 0 }}
                                                    animate={{ opacity: 1 }}
                                                    exit={{ opacity: 0 }}
                                                    transition={reduceMotion ? INSTANT_TRANSITION : FADE_TRANSITION}
                                                    className="min-w-0"
                                                >
                                                    <Typography
                                                        size="h5"
                                                        weight="bold"
                                                        truncate
                                                        text={title}
                                                    />
                                                </motion.div>
                                            ) : null}
                                        </AnimatePresence>
                                    ),
                                    () => (
                                        <ButtonBase
                                            isIconOnly
                                            variant="ghost"
                                            size="sm"
                                            ariaLabel={collapsed ? expandLabel : collapseLabel}
                                            prefixIcon={SidebarSimpleIcon}
                                            onPress={toggle}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        // pinned top slot (e.g. resume pill) — above the scroll area, always
                        // visible. min-w-0: a column-flex item defaults to content-width
                        // (min-width: auto), which would let it overflow the rail and get
                        // hard-clipped by overflow-hidden instead of shrinking so its own
                        // `truncate` text can ellipsize.
                        () => (
                            <FillAvailable
                                at="base"
                                body={() => <>{topSlot}</>}
                            />
                        ),
                        // body: the nav — ALWAYS rendered; row content decides its own icon-only
                        // look off `useSidebarCollapsed`. `DragScrollArea` owns the overflow
                        // (hidden scrollbar + Windows-safe pointer-pan); `StackV` gives the
                        // column its `gap={4}` rhythm and default `align="stretch"` (rows
                        // fill the rail's width whether expanded or collapsed), since the scroll
                        // frame itself lays out nothing.
                        // HOLD: no house NavLandmark frame owns `<nav>` + column flex-fill yet.
                        () => (
                            <nav className="flex min-h-0 flex-1 flex-col">
                                <DragScrollArea size={40} className="flex-1">
                                    <StackV gap={4} items={[() => children]} />
                                </DragScrollArea>
                            </nav>
                        ),
                    ]}
                />
            </motion.aside>
        </SidebarCollapsedContext.Provider>
    )
}

import React from "react"
import { QuotaBar } from "@/components/blocks/ai/QuotaBar"
import { StackV } from "@/components/frames/Stack"

/**
 * `AiQuotaLane` — one lane's pair of rolling-window quota bars ("next 5 hours"
 * above "this week"), shared by the Auto tab and the Premium branch of the
 * Subscription tab inside `AiQuotaModal`. Both rows are the same `QuotaBar`
 * composition reading a different window. Unset `data`/`isLoading` shimmers
 * both bars.
 */

/** One rolling-window quota reading, ready to draw as a single {@link ProgressBar}. */
export interface AiQuotaWindow {
    /** Amount consumed in this window. */
    used: number
    /** Cap for this window (`0` reads as "no allowance"). */
    limit: number
    /** Reset line under the bar (e.g. `"Resets at 18:50 on 06/01"`). `null`/unset → no line. */
    resetLabel?: string | null
}

/** The two rolling windows one {@link AiQuotaLane} tracks. */
export interface AiQuotaLaneData {
    /** Next-5-hours rolling window. */
    window5h: AiQuotaWindow
    /** This-week rolling window. */
    windowWeek: AiQuotaWindow
}

/** Props for {@link AiQuotaLane}. */
export interface AiQuotaLaneProps {
    /** The lane's two windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` → this lane's own fetch is in flight; both bars draw their skeleton mirror. */
    isLoading: boolean
}

/**
 * The lane's two bars. See the file header for what it owns (window labels)
 * and what it deliberately does not (fetching — `data` is a plain prop, never
 * an internal SWR call — and the fill-tone ramp, which `QuotaBar` owns).
 *
 * @param props - {@link AiQuotaLaneProps}
 */
const AiQuotaLane = ({ data, isLoading }: AiQuotaLaneProps) => {
    const showSkeleton = isLoading || !data

    return (
        <StackV
            identity={{ tier: "block", component: "AiQuotaLane" }}
            gap={4}
            items={[
                () => (
                    <QuotaBar
                        label="Next 5 hours"
                        used={data?.window5h.used ?? 0}
                        limit={data?.window5h.limit ?? 0}
                        resetLabel={data?.window5h.resetLabel}
                        isSkeleton={showSkeleton}
                    />
                ),
                () => (
                    <QuotaBar
                        label="This week"
                        used={data?.windowWeek.used ?? 0}
                        limit={data?.windowWeek.limit ?? 0}
                        resetLabel={data?.windowWeek.resetLabel}
                        isSkeleton={showSkeleton}
                    />
                ),
            ]}
        />
    )
}

export { AiQuotaLane }

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"

/**
 * One placeholder row for the Loading branch — avatar + 2 text bars +
 * chip-pill row + status dot, ported verbatim from the real
 * `CourseQaSkeleton.tsx` shape (*1).
 *
 * `align="start"` on the outer row (instead of the real file's `mt-2` on the
 * dot) top-aligns all three children without a child pushing its own margin
 * (§10a — the padding gate only allows a parent's `gap`/surface `padding` to
 * own a seam).
 */
export const SkeletonQuestionRow = () => {
    const previewLines = (
        <>
            <Typography size="sm" isSkeleton classNames={["w-full"]} />
            <Typography size="sm" isSkeleton classNames={["w-2/3"]} />
        </>
    )

    const chipRow = (
        <>
            <Typography size="xs" isSkeleton classNames={["w-1/3"]} />
            <Chip isSkeleton />
        </>
    )

    const textColumn = (
        <>
            {/* asker + time line */}
            <Typography size="xs" isSkeleton classNames={["w-1/3"]} />
            {/* two-line preview */}
            <StackV gap={2} items={[() => previewLines]} />
            {/* chip-pill row — ONE chip (status, the classification axis) + the scope
 as a plain shimmer bar, matching the real row's own text-inline treatment
 (eslint `starci-fe/no-adjacent-chip`, *7 below). */}
            <StackH gap={3} items={[() => chipRow]} />
        </>
    )

    return (
        <StackH identity={{ tier: "block", component: "SkeletonQuestionRow" }}
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"

            items={[
                () => (
                    <div className="shrink-0">
                        <Avatar isSkeleton size="sm" />
                    </div>
                ),
                () => <StackV gap={2} classNames={["min-w-0", "flex-1"]} items={[() => textColumn]} />,
                // status dot — no home atom (*3), same escape hatch `Pagination` uses for its own shimmer squares
                () => <Skeleton className="size-2 shrink-0 rounded-full" />,
            ]}
        />
    )
}

import React from "react"
import { SpeakerHighIcon, SpeakerSlashIcon } from "@phosphor-icons/react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `InterviewerPresence` — "someone is interviewing you": persona, live-speaking
 * cue, TTS toggle, and the question underneath. Whether the question region
 * exists is presence/absence data on the same shape — an idle and a mid-question
 * interviewer are one block with different data. `speaking` (audio) and `isAsking`
 * (text still streaming) are independent props; the identity row composes `Avatar`
 * + `Typography` directly (role, not a handle, plus a pulse ring).
 */

/** Who is interviewing — identity only, no session state. */
export interface InterviewerPresencePersona {
    /** Display name, e.g. "Ms. Mai". */
    name: string
    /** Static role/title shown under the name, e.g. "Backend Engineer". */
    role: string
    /** Uploaded avatar URL. Missing, or failing to load, falls back through `Avatar`'s own chain. */
    avatarSrc?: string
}

/** Props for {@link InterviewerPresence}. */
export interface InterviewerPresenceProps {
    /** Who is interviewing. */
    persona: InterviewerPresencePersona
    /**
     * `true` while TTS audio is actively voicing the current question. Drives
     * ONLY the pulse ring + status line — see the file header for why this is
     * independent from `isAsking`.
     */
    speaking: boolean
    /** Status text shown beside the pulse while `speaking` is true, e.g. "Reading the question". Localized by the caller. */
    speakingLabel: string
    /**
     * `true` → this session offers a TTS toggle at all. Omitted/`false` → the
     * toggle is not drawn: a control that cannot do anything is not a control
     * (same reasoning as `ContentModeNav`'s language switcher below two languages).
     */
    ttsSupported?: boolean
    /** Current TTS on/off state. Only read while `ttsSupported` is true. */
    ttsEnabled?: boolean
    /** Fired when the learner presses the toggle. Only read while `ttsSupported` is true. */
    onToggleTts?: () => void
    /** Toggle's accessible label for the moment TTS is ON (pressing it mutes). */
    muteLabel: string
    /** Toggle's accessible label for the moment TTS is OFF (pressing it unmutes). */
    unmuteLabel: string
    /**
     * The current question, as authored/streamed markdown. Absent or blank →
     * no question region at all — the interviewer is between questions.
     */
    questionMarkdown?: string
    /**
     * `true` while this question's TEXT is still arriving. Adds a typing cue
     * under the question; has no effect once `questionMarkdown` is blank —
     * there is nothing yet to attach the cue to.
     */
    isAsking?: boolean
}

/**
 * The interviewer's presence header: identity, live-speaking cue, TTS toggle,
 * and the question underneath. See the file header for the full contract.
 *
 * @param props - {@link InterviewerPresenceProps}
 */
const InterviewerPresence = ({
    persona,
    speaking,
    speakingLabel,
    ttsSupported = false,
    ttsEnabled,
    onToggleTts,
    muteLabel,
    unmuteLabel,
    questionMarkdown,
    isAsking = false,
}: InterviewerPresenceProps) => {
    const hasQuestion = Boolean(questionMarkdown && questionMarkdown.trim().length > 0)
    // A control that cannot do anything is not drawn — mirrors ContentModeNav's
    // language switcher, which only appears once it has two real options.
    const canToggleTts = ttsSupported && ttsEnabled != null && onToggleTts != null
    const TtsIcon = ttsEnabled ? SpeakerHighIcon : SpeakerSlashIcon
    // The icon shows the CURRENT state; the label names the ACTION the press performs.
    const ttsAriaLabel = ttsEnabled ? muteLabel : unmuteLabel

    // Relative wrapper only to anchor the decorative pulse ring — not a
    // spacing seam, so it stays a plain span rather than a frame.
    const avatarWithPulse = (
        <span className="relative inline-flex shrink-0">
            {speaking ? (
                <span
                    aria-hidden
                    className="absolute -inset-1 animate-ping rounded-full ring-2 ring-accent"
                />
            ) : null}
            <Avatar
                name={persona.name}
                src={persona.avatarSrc}
                seed={persona.name}
                size="lg"

            />
        </span>
    )

    const speakingStatus = speaking ? (
        <StackH
            gap={2}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"

            items={[
                () => <span aria-hidden className="size-1.5 animate-pulse rounded-full bg-accent" />,
                () => (
                    <Typography
                        text={speakingLabel}
                        size="sm"
                        color="accent"
                        weight="medium"

                    />
                ),
            ]}
        />
    ) : null

    const nameAndRole = (
        <StackV
            gap={1}
            principle="name-handle"
            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."

            items={[
                () => (
                    <Typography
                        text={persona.name}
                        weight="medium"

                    />
                ),
                () => (
                    <StackH
                        gap={3}
                        principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        align="center"

                        items={[
                            () => (
                                <Typography
                                    text={persona.role}
                                    size="sm"
                                    color="muted"

                                />
                            ),
                            () => speakingStatus,
                        ]}
                    />
                ),
            ]}
        />
    )

    const identity = (
        <StackH
            gap={3}
            principle="identity"
            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
            align="center"

            items={[
                () => avatarWithPulse,
                () => nameAndRole,
            ]}
        />
    )

    const toggleButton = canToggleTts ? (
        <Button
            isIconOnly
            variant="ghost"
            prefixIcon={TtsIcon}
            ariaLabel={ttsAriaLabel}
            onPress={onToggleTts}

        />
    ) : null

    const headerRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center"
            justify="between"

            items={[
                () => identity,
                () => toggleButton,
            ]}
        />
    )

    const typingDots = isAsking ? (
        <StackH
            gap={2}
            principle="separator-dot"
            explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
            align="center"

            items={[
                () => <span aria-hidden className="size-1.5 animate-bounce rounded-full bg-muted" />,
                () => <span aria-hidden className="size-1.5 animate-bounce rounded-full bg-muted [animation-delay:150ms]" />,
                () => <span aria-hidden className="size-1.5 animate-bounce rounded-full bg-muted [animation-delay:300ms]" />,
            ]}
        />
    ) : null

    const questionRegion = hasQuestion ? (
        <StackV
            gap={2}

            items={[
                () => (
                    <MarkdownContent
                        source={questionMarkdown as string}
                        measure="reading"


                    />
                ),
                () => typingDots,
            ]}
        />
    ) : null

    return (
        <div>
            <StackV
                gap={3}

                items={[
                    () => headerRow,
                    () => questionRegion,
                ]}
            />
        </div>
    )
}

export { InterviewerPresence }

"use client"

import React, { createContext, useContext, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { motion, AnimatePresence, useReducedMotion } from "framer-motion"
import { cn } from "@heroui/react"
import { SidebarSimpleIcon } from "@phosphor-icons/react"
import { ButtonBase } from "@/components/atoms/buttons/Button/ButtonBase"
import { Typography } from "@/components/atoms/text/Typography"
import { DragScrollArea } from "@/components/behaviors/DragScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"

